mapper.select:
SELECT SEQNO SEQNO, AMOUNT AMOUNT, TRADE_ID TRADE_ID, IS_BOTTOM IS_BOTTOM, CREDIT_OCCURE_TYPE CREDIT_OCCURE_TYPE, ENTRUST_ID ENTRUST_ID, '02' creditUsingType, #{operatioMode} operatioMode FROM CREDIT_USING_AST temp
and temp.CDATE = to_date(#{executeDate},'yyyy-MM-dd')
and temp.STATUS = #{status}
and temp.CREDIT_OCCURE_TYPE = #{creditOccureType}
order by temp.CREATE_TIME desc

SELECT SEQNO SEQNO, AMOUNT AMOUNT, TRADE_ID TRADE_ID, IS_BOTTOM IS_BOTTOM, CREDIT_OCCURE_TYPE CREDIT_OCCURE_TYPE, ENTRUST_ID ENTRUST_ID, '01' creditUsingType, #{operatioMode} operatioMode FROM CREDIT_USING_CUSTOMER temp
and temp.CDATE = to_date(#{executeDate},'yyyy-MM-dd')
and temp.STATUS = #{status}
and temp.CREDIT_OCCURE_TYPE = #{creditOccureType}
order by temp.CREATE_TIME desc
